"use strict";
/* ============================== Levels 23 to 50 ==============================
   Handmade extra levels, after the Server Farm (22). They are added to EXTRAS,
   so extraDef(23..50) returns them; past 50 the levels are generated again.
   Each one says in its intro which monsters live there and how to survive
   them. The new monsters (Lookalike, Wall Crawler, Janitor, Static) are in
   MT and BEST in index.html; the new ambiences are in ambience(). */
(function(){
// one level: n is its number; en and pt hold the name and the texts
function X(n,o,en,pt){return {...o,name:`Level ${n}, ${en.title}`,short:String(n),exitWhat:en.exitWhat,intro:`Level ${n}, ${en.title}. ${en.intro}`,exitText:en.exitText,flavor:en.flavor,
  pt:{name:`Nível ${n}, ${pt.title}`,short:String(n),exitWhat:pt.exitWhat,intro:`Nível ${n}, ${pt.title}. ${pt.intro}`,exitText:pt.exitText,flavor:pt.flavor}};}

EXTRAS.push(
X(23,{w:12,h:10,loops:0.22,mons:['janitor','wretch','smiler'],dark:0.4,lights:true,hides:4,music:'music24',items:{water:3,fire:2,battery:3,energy:2},
  wall:[190,12,70],floor:[200,8,60],ceil:[200,6,82],amb:'laundry',step:'tile',beacon:'bell'},
 {title:'The Laundromat',exitWhat:'a dryer buzzer going off',
  intro:'Rows of washing machines thump and spin in the dark, full of clothes nobody will ever come back for. A squeaking cart rolls between them: the Janitor. It is slow, but it never stops, and it cleans up anything you leave behind, glow sticks, wind chimes, even your mark. Find the dryer buzzer by the exit.',
  exitText:'You open the buzzing dryer. Inside there is no drum, only a warm, dark tunnel, and the smell of clean sheets. You crawl in, and it starts to spin.',
  flavor:['A washing machine stops mid-cycle. The door is open. It is empty, and still wet.','Every sock on the floor is a single sock. None of them match.','A sign on the wall says: do not leave your belongings unattended. Underlined, three times.','The detergent smells like almond water.','Someone has folded a sweater on the table. Still warm.']},
 {title:'A Lavanderia',exitWhat:'o alarme de uma secadora tocando',
  intro:'Fileiras de máquinas de lavar batem e giram no escuro, cheias de roupas que ninguém vai voltar para buscar. Um carrinho que range passa entre elas: o Zelador. Ele é lento, mas nunca para, e limpa tudo o que você deixa para trás, bastões de luz, sinos de vento, até a sua marca. Encontre o alarme da secadora perto da saída.',
  exitText:'Você abre a secadora que apita. Lá dentro não tem tambor, só um túnel quente e escuro, com cheiro de lençol limpo. Você entra rastejando, e ele começa a girar.',
  flavor:['Uma máquina para no meio da lavagem. A porta está aberta. Está vazia, e ainda molhada.','Todas as meias no chão estão sozinhas. Nenhuma combina.','Uma placa na parede diz: não deixe seus pertences sem supervisão. Sublinhado, três vezes.','O sabão tem cheiro de água de amêndoa.','Alguém dobrou um suéter em cima da mesa. Ainda está quente.']}),

X(24,{w:12,h:10,loops:0.25,mons:['lookalike','lookalike','hound'],dark:0.3,lights:true,hides:4,music:'music25',items:{water:5,fire:2,battery:4,energy:3},
  wall:[35,25,55],floor:[30,15,40],ceil:[40,10,75],amb:'hum',step:'concrete',beacon:'buzz'},
 {title:'The Storeroom',exitWhat:'a buzzing exit sign over the loading dock',
  intro:'Endless metal shelves, stocked with everything you need. Too much of it. Something here has learned to look like supplies. The Lookalike folds itself up small and waits, pretending to be almond water or a battery. Real things chime clear and steady. The Lookalike chimes too, but its chime wavers, just slightly. Listen before you reach for anything. A Hound guards the aisles. Find the buzzing exit sign over the loading dock.',
  exitText:'You push through the plastic strips of the loading dock. The floor is a conveyor belt, and it carries you, slowly, into a narrow dark hallway.',
  flavor:['A whole shelf of almond water. One of the bottles is breathing.','A price tag says: free. Then, in smaller letters: for now.','Something on the top shelf shifts when you look away.','Every box is labelled with today\'s date.','A shopping cart sits in the middle of the aisle, full of batteries, abandoned in a hurry.']},
 {title:'O Depósito',exitWhat:'uma placa de saída zumbindo sobre a doca de carga',
  intro:'Prateleiras de metal sem fim, cheias de tudo o que você precisa. Coisa demais. Algo aqui aprendeu a parecer suprimento. O Sósia se dobra todo e espera, fingindo ser água de amêndoa ou uma pilha. Coisas de verdade tilintam claro e firme. O Sósia também tilinta, mas o tilintar dele oscila, só um pouquinho. Escute antes de pegar qualquer coisa. Um Cão vigia os corredores. Encontre a placa de saída zumbindo sobre a doca de carga.',
  exitText:'Você passa pelas tiras de plástico da doca de carga. O chão é uma esteira, e ela leva você, devagar, para um corredor estreito e escuro.',
  flavor:['Uma prateleira inteira de água de amêndoa. Uma das garrafas está respirando.','Uma etiqueta de preço diz: grátis. Embaixo, em letras menores: por enquanto.','Algo na prateleira de cima se mexe quando você desvia o olhar.','Toda caixa tem a data de hoje.','Um carrinho de compras está no meio do corredor, cheio de pilhas, abandonado às pressas.']}),

X(25,{w:12,h:10,loops:0.06,mons:['wallcrawler','wallcrawler'],dark:0.45,lights:true,hides:5,music:'music26',items:{water:3,fire:2,battery:3,energy:2},
  wall:[40,30,50],floor:[30,20,32],ceil:[40,15,70],amb:'drip',step:'carpet',beacon:'phone'},
 {title:'The Narrow Halls',exitWhat:'a phone ringing at the end of the hall',
  intro:'The hallways here are barely wider than your shoulders, and the walls are hollow. Something lives inside them. The Wall Crawler scratches along beside you, through the plaster. It cannot reach the middle of the hall, but if you stand still next to the wall it is in, or hide, it reaches through. Keep moving. Hiding spots are not safe here. Find the phone ringing at the end of the hall.',
  exitText:'You pick up the phone. On the other end, someone is scratching at the receiver. The wall behind you opens like a door, and you fall through it, into static.',
  flavor:['The wallpaper bulges outward, then slowly flattens again.','There are fingernail marks on the inside of a light switch cover.','A picture frame hangs crooked. Behind it, a hole the size of a hand.','You knock on the wall. Something knocks back, twice.','The hall is so narrow that your shoulders brush both walls. Both of them are warm.']},
 {title:'Os Corredores Estreitos',exitWhat:'um telefone tocando no fim do corredor',
  intro:'Os corredores aqui mal têm a largura dos seus ombros, e as paredes são ocas. Algo vive dentro delas. O Rastejador das Paredes arranha ao seu lado, através do reboco. Ele não alcança o meio do corredor, mas se você ficar parado perto da parede onde ele está, ou se esconder, ele atravessa. Continue andando. Esconderijos não são seguros aqui. Encontre o telefone tocando no fim do corredor.',
  exitText:'Você atende o telefone. Do outro lado, alguém arranha o fone. A parede atrás de você se abre como uma porta, e você cai através dela, dentro da estática.',
  flavor:['O papel de parede estufa para fora, e depois volta a ficar liso, devagar.','Tem marcas de unha do lado de dentro do espelho de um interruptor.','Um quadro está torto. Atrás dele, um buraco do tamanho de uma mão.','Você bate na parede. Algo bate de volta, duas vezes.','O corredor é tão estreito que seus ombros encostam nas duas paredes. As duas estão quentes.']}),

X(26,{w:12,h:10,loops:0.2,mons:['static','static','skin'],dark:0.55,lights:true,hides:4,music:'music27',items:{water:3,fire:2,battery:3,energy:2,radio:1},
  wall:[220,10,30],floor:[220,8,22],ceil:[220,8,15],amb:'radio',step:'carpet',beacon:'radio'},
 {title:'The Radio Station',exitWhat:'an old song playing on the on-air speaker',
  intro:'A radio station that never stopped broadcasting. Every speaker hisses, and somewhere a DJ is still talking to nobody. Two Statics drift through the studios. They are made of radio noise and nearly deaf, but every time you use your walkie-talkie, they come straight for you. Use it only when you must. The Skin-Stealer is here too, and it can sound like anyone. Find the old song on the on-air speaker.',
  exitText:'You turn the dial on the speaker all the way up. The song gets louder and louder, until the room is only music, and then only dark trees.',
  flavor:['A red ON AIR light blinks over a door. Behind it, someone breathes into a microphone.','The DJ is reading the weather for a city that does not exist.','A request line is ringing. The caller ID shows your name.','Hundreds of records are stacked on the floor. Every label is blank.','A voice on the radio says: and that one goes out to the person in the hallway.']},
 {title:'A Estação de Rádio',exitWhat:'uma música antiga tocando no alto-falante do ar',
  intro:'Uma estação de rádio que nunca parou de transmitir. Todo alto-falante chia, e em algum lugar um locutor ainda fala para ninguém. Duas Estáticas flutuam pelos estúdios. Elas são feitas de chiado de rádio e quase surdas, mas toda vez que você usa o walkie-talkie, elas vêm direto até você. Use só quando precisar. O Ladrão de Pele também está aqui, e ele pode soar como qualquer pessoa. Encontre a música antiga no alto-falante do ar.',
  exitText:'Você gira o botão do alto-falante até o fim. A música fica mais alta e mais alta, até a sala ser só música, e depois só árvores escuras.',
  flavor:['Uma luz vermelha de NO AR pisca sobre uma porta. Atrás dela, alguém respira num microfone.','O locutor está lendo a previsão do tempo de uma cidade que não existe.','A linha de pedidos está tocando. O identificador mostra o seu nome.','Centenas de discos empilhados no chão. Todos os rótulos estão em branco.','Uma voz no rádio diz: e essa vai para a pessoa no corredor.']}),

X(27,{w:13,h:10,loops:0.3,mons:['hound','hound','watcher'],dark:0.75,lights:false,hides:4,music:'music32',items:{water:3,fire:3,battery:4,energy:2},
  wall:[110,30,18],floor:[95,30,15],ceil:[230,40,8],amb:'forest',step:'grass',beacon:'fireplace'},
 {title:'The Night Forest',exitWhat:'a campfire crackling in a clearing',
  intro:'A forest at night, where the trees are planted in perfect rows and every path loops back on itself. Owls call from branches you cannot see. Hounds hunt here in a pack. When one howls, the others answer and close in from different sides. Something watches from between the trunks, too. Listen, and it freezes. Find the campfire crackling in a clearing.',
  exitText:'You sit by the campfire to warm your hands. The flames rise into the shape of a cinema screen, and when you look up, you are sitting in a red velvet seat.',
  flavor:['The trees are all exactly the same distance apart.','A tent is pitched beside the path. The zipper is open from the inside.','The moon is a fluorescent light, humming.','Something has carved a smiley face into every tree on this path.','You step on a twig. Somewhere far away, someone else steps on a twig.']},
 {title:'A Floresta Noturna',exitWhat:'uma fogueira estalando numa clareira',
  intro:'Uma floresta à noite, onde as árvores são plantadas em fileiras perfeitas e todo caminho volta para si mesmo. Corujas piam em galhos que você não vê. Cães caçam aqui em matilha. Quando um uiva, os outros respondem e cercam você de lados diferentes. Algo também observa entre os troncos. Escute, e ele congela. Encontre a fogueira estalando numa clareira.',
  exitText:'Você senta perto da fogueira para esquentar as mãos. As chamas sobem no formato de uma tela de cinema, e quando você olha para cima, está sentado numa poltrona de veludo vermelho.',
  flavor:['As árvores estão todas exatamente à mesma distância umas das outras.','Uma barraca está montada ao lado da trilha. O zíper está aberto por dentro.','A lua é uma lâmpada fluorescente, zumbindo.','Alguém entalhou uma carinha sorridente em toda árvore desta trilha.','Você pisa num galho. Bem longe, outra pessoa pisa num galho.']}),

X(28,{w:12,h:9,loops:0.2,mons:['toon','smiler','mimic'],dark:0.8,lights:false,hides:5,music:'music33',items:{water:3,fire:2,battery:4,energy:2},
  wall:[355,55,22],floor:[355,40,15],ceil:[0,0,8],amb:'cinema',step:'carpet',beacon:'chime'},
 {title:'The Cinema',exitWhat:'the intermission chime',
  intro:'A movie theatre where the film never ends. The projector clatters, and on the screen a cartoon laughs at a joke nobody told. The Toon climbed out of the screen. Its rubber arms stretch two rooms, so keep your distance. A Smiler grins in the dark rows, and the Mimic hums in a voice you know. Keep your flashlight ready. Find the intermission chime.',
  exitText:'The chime rings, and the lights come up. Everyone in the theatre turns to look at you. Then the floor tilts, and you slide down the aisle into cold, rushing water.',
  flavor:['The film on the screen is a recording of you, walking into this room.','Every seat is folded down, as if someone is sitting in it.','Popcorn crunches under your feet. It is still warm.','A sign says: please turn off your phones. And your flashlights. And your heartbeat.','The audience laughs. You are the only one here.']},
 {title:'O Cinema',exitWhat:'o sino do intervalo',
  intro:'Um cinema onde o filme nunca acaba. O projetor estala, e na tela um desenho ri de uma piada que ninguém contou. O Desenho saiu da tela. Os braços de borracha dele esticam duas salas, então mantenha distância. Um Sorridente sorri nas fileiras escuras, e o Imitador cantarola numa voz que você conhece. Deixe a lanterna pronta. Encontre o sino do intervalo.',
  exitText:'O sino toca, e as luzes acendem. Todo mundo no cinema se vira para olhar você. Então o chão se inclina, e você escorrega pelo corredor até uma água fria e corrente.',
  flavor:['O filme na tela é uma gravação de você, entrando nesta sala.','Todas as poltronas estão abaixadas, como se alguém estivesse sentado nelas.','Pipoca estala sob os seus pés. Ainda está quente.','Uma placa diz: por favor, desliguem os celulares. E as lanternas. E o coração.','A plateia ri. Você é a única pessoa aqui.']}),

X(29,{w:12,h:8,loops:0.18,mons:['deep','wallcrawler','wretch'],dark:0.5,lights:false,hides:2,water:0.4,music:'music28',items:{water:3,fire:2,battery:3,energy:2},
  wall:[95,20,25],floor:[90,25,18],ceil:[95,15,15],amb:'sewer',step:'concrete',beacon:'air'},
 {title:'The Sewers',exitWhat:'fresh air blowing down through a grate',
  intro:'Brick tunnels, half flooded, with black water that never stops moving. The Thing in the Water hunts anyone who wades in, so stay on the dry walkways when you can. The Wall Crawler scratches inside the old brick, so do not stand still against it. A Wretch shrieks when it sees you. Find the fresh air blowing down through a grate.',
  exitText:'You climb the ladder under the grate. At the top there is no street, only a stone floor, cold air, and the deep hum of an organ.',
  flavor:['Something floats past in the water. A rubber duck. It turns to watch you.','The bricks are numbered. The numbers count down.','A pipe gurgles a word. It sounds like your name.','The water is warm, which is worse.','Graffiti on the wall says: it lives in the walls too.']},
 {title:'Os Esgotos',exitWhat:'ar fresco soprando por uma grade',
  intro:'Túneis de tijolo, meio alagados, com uma água preta que nunca para de se mexer. A Coisa na Água caça quem entra nela, então fique nas passarelas secas quando puder. O Rastejador das Paredes arranha dentro dos tijolos velhos, então não fique parado encostado neles. Um Miserável grita quando vê você. Encontre o ar fresco soprando por uma grade.',
  exitText:'Você sobe a escada debaixo da grade. Lá em cima não tem rua, só um chão de pedra, um ar frio, e o zumbido grave de um órgão.',
  flavor:['Algo passa flutuando na água. Um patinho de borracha. Ele vira para olhar você.','Os tijolos são numerados. Os números diminuem.','Um cano gorgoleja uma palavra. Parece o seu nome.','A água está morna, o que é pior.','Uma pichação na parede diz: ele vive nas paredes também.']}),

X(30,{w:12,h:10,loops:0.2,mons:['wretch','smiler','mimic'],dark:0.55,lights:true,hides:4,puzzle:'bell',music:'music29',items:{water:3,fire:2,battery:3,energy:2},
  wall:[30,10,45],floor:[25,8,30],ceil:[30,8,20],amb:'church',step:'concrete',beacon:'bell'},
 {title:'The Abandoned Church',exitWhat:'a church bell tolling',
  intro:'Stone pews in endless rows, and an organ playing one long note by itself. A Wretch shrieks in the dark, a Smiler grins between the pews, and the Mimic sings along with the organ. Find the tolling bell.',
  exitText:'The bell tolls one last time, and the floor of the church opens like a trap door. You fall, past clanking chains and hissing steam, onto a moving belt.',
  flavor:['Every candle is lit. None of them give off heat.','The hymn numbers on the board read: 0, 0, 0.','A confession booth curtain moves. Someone inside whispers: your turn.','The stained glass shows a hallway. A yellow hallway.','The organ\'s note bends, just slightly, like a breath.']},
 {title:'A Igreja Abandonada',exitWhat:'um sino de igreja badalando',
  intro:'Bancos de pedra em fileiras sem fim, e um órgão tocando uma nota longa sozinho. Um Miserável grita no escuro, um Sorridente sorri entre os bancos, e o Imitador canta junto com o órgão. Encontre o sino que badala.',
  exitText:'O sino badala uma última vez, e o chão da igreja se abre como um alçapão. Você cai, passando por correntes batendo e vapor chiando, em cima de uma esteira em movimento.',
  flavor:['Toda vela está acesa. Nenhuma esquenta.','Os números dos hinos no quadro dizem: 0, 0, 0.','A cortina de um confessionário se mexe. Alguém lá dentro sussurra: sua vez.','O vitral mostra um corredor. Um corredor amarelo.','A nota do órgão se curva, só um pouquinho, como uma respiração.']}),

X(31,{w:13,h:10,loops:0.18,mons:['hound','howler','janitor'],dark:0.35,lights:true,hides:3,hazards:0.08,puzzle:'breaker',music:'music34',items:{water:3,fire:2,battery:3,energy:2},
  wall:[25,30,35],floor:[30,10,25],ceil:[30,10,18],amb:'factory',step:'metal',beacon:'engine'},
 {title:'The Factory Floor',exitWhat:'a freight elevator engine idling',
  intro:'Stamping presses slam down in a steady rhythm, making nothing. Live wires hang everywhere, so listen for the crackle before you step. A Hound and the Howler hunt between the machines, and the Janitor mops up after them. Find the idling elevator engine.',
  exitText:'The elevator shudders up. The doors open on a room painted pastel blue, full of tiny chairs and the tinkling of a music box.',
  flavor:['A conveyor belt carries boxes past you. Every box is empty and taped shut.','A time card machine has punched in the same name ten thousand times. Yours.','The presses slam in the rhythm of a heartbeat. It speeds up when you run.','A safety sign says: days without an accident. The number is blank.','Hard hats hang on hooks by the door. One of them is still warm.']},
 {title:'O Chão da Fábrica',exitWhat:'o motor de um elevador de carga ligado',
  intro:'Prensas descem batendo num ritmo constante, sem fabricar nada. Há fios desencapados por toda parte, então escute o estalo antes de dar um passo. Um Cão e o Uivador caçam entre as máquinas, e o Zelador limpa depois deles. Encontre o motor do elevador ligado.',
  exitText:'O elevador sobe tremendo. As portas se abrem numa sala pintada de azul claro, cheia de cadeirinhas e do tilintar de uma caixinha de música.',
  flavor:['Uma esteira leva caixas ao seu lado. Toda caixa está vazia e fechada com fita.','Um relógio de ponto marcou o mesmo nome dez mil vezes. O seu.','As prensas batem no ritmo de um coração. Ele acelera quando você corre.','Uma placa de segurança diz: dias sem acidentes. O número está em branco.','Capacetes pendurados nos ganchos perto da porta. Um deles ainda está quente.']}),

X(32,{w:12,h:10,loops:0.22,mons:['party','toon','lookalike'],dark:0.3,lights:true,hides:5,music:'musicbox',items:{water:4,fire:2,battery:3,energy:3},
  wall:[200,45,80],floor:[45,40,70],ceil:[200,30,90],amb:'nursery',step:'carpet',beacon:'piano'},
 {title:'The Daycare',exitWhat:'a toy piano playing a lullaby',
  intro:'A daycare with pastel walls, tiny chairs, and toys everywhere, but no children. A music box plays the same song over and over. A Partygoer wants to celebrate with you, the Toon wants to play, and one of the toys is not a toy. The Lookalike hides among the snacks. Real things chime steady. Its chime wavers. Find the toy piano playing a lullaby.',
  exitText:'You press the last key of the lullaby. The piano lid slams shut on its own, and the lights go out. When they come back, you are lying on a cold steel table.',
  flavor:['The finger paintings on the wall are all of a long yellow hallway.','A cubby has your name on it. Inside, a drawing of you, from behind.','Every doll in the room is facing the door.','Nap mats are laid out in rows. One of them is warm, and the blanket is moving.','A sticker chart says: good job! The stars have been scratched out.']},
 {title:'A Creche',exitWhat:'um pianinho de brinquedo tocando uma canção de ninar',
  intro:'Uma creche com paredes em tons pastel, cadeirinhas e brinquedos por toda parte, mas nenhuma criança. Uma caixinha de música toca a mesma canção sem parar. Um Festeiro quer comemorar com você, o Desenho quer brincar, e um dos brinquedos não é brinquedo. O Sósia se esconde entre os lanches. Coisas de verdade tilintam firme. O dele oscila. Encontre o pianinho tocando uma canção de ninar.',
  exitText:'Você aperta a última tecla da canção. A tampa do piano se fecha sozinha, e as luzes se apagam. Quando voltam, você está deitado numa mesa de aço gelada.',
  flavor:['Todas as pinturas a dedo na parede mostram um corredor amarelo e comprido.','Um escaninho tem o seu nome. Dentro, um desenho de você, de costas.','Toda boneca da sala está virada para a porta.','Colchonetes estão arrumados em fileiras. Um deles está quente, e o cobertor está se mexendo.','Um quadro de estrelinhas diz: bom trabalho! As estrelas foram riscadas.']}),

X(33,{w:12,h:10,loops:0.16,mons:['patient','patient','wallcrawler'],dark:0.6,lights:true,hides:4,music:'music30',items:{water:3,fire:2,battery:4,energy:2},
  wall:[190,8,60],floor:[190,6,45],ceil:[190,6,70],amb:'morgue',step:'tile',beacon:'buzz'},
 {title:'The Morgue',exitWhat:'a cooler alarm buzzing',
  intro:'Cold steel drawers line every wall, and the refrigeration hums so loud you can feel it in your teeth. The Patients have climbed out of their drawers, and you will hear their gurney wheels squeak. Something else lives behind the drawers, in the walls. The Wall Crawler cannot reach you while you keep moving. Do not stand still. Find the buzzing cooler alarm.',
  exitText:'You open the alarm\'s panel, and a whole wall of drawers slides out at once, like a staircase. You climb up, and up, into flashing lights and the chirp of a hundred arcade games.',
  flavor:['A toe tag hangs from an empty drawer. The name on it is yours.','Your breath fogs in the air. Something else\'s breath fogs beside it.','A clipboard lists today\'s arrivals. The list goes on for a hundred pages.','One drawer is slightly open. From inside, someone says: close it, please.','The scale in the corner reads a weight, but nothing is on it.']},
 {title:'O Necrotério',exitWhat:'o alarme de uma câmara fria apitando',
  intro:'Gavetas de aço geladas cobrem todas as paredes, e a refrigeração zumbe tão alto que dá para sentir nos dentes. Os Pacientes saíram das gavetas, e você vai ouvir as rodinhas das macas rangendo. Outra coisa vive atrás das gavetas, nas paredes. O Rastejador das Paredes não alcança você enquanto você continuar andando. Não fique parado. Encontre o alarme da câmara fria apitando.',
  exitText:'Você abre o painel do alarme, e uma parede inteira de gavetas desliza para fora de uma vez, como uma escada. Você sobe, e sobe, até luzes piscando e o apito de cem fliperamas.',
  flavor:['Uma etiqueta de dedão pende de uma gaveta vazia. O nome nela é o seu.','Sua respiração faz fumaça no ar. A respiração de outra coisa faz fumaça ao lado.','Uma prancheta lista as chegadas de hoje. A lista tem cem páginas.','Uma gaveta está entreaberta. Lá de dentro, alguém diz: fecha, por favor.','A balança no canto marca um peso, mas não tem nada em cima.']}),

X(34,{w:12,h:10,loops:0.22,mons:['glitch','toon','party'],dark:0.5,lights:true,hides:4,codelock:true,music:'music31',items:{water:3,fire:2,battery:4,energy:2},
  wall:[270,50,25],floor:[260,40,15],ceil:[270,30,8],amb:'arcade',step:'carpet',beacon:'striker'},
 {title:'The Arcade',exitWhat:'a prize bell ringing at the prize counter',
  intro:'Rows of arcade cabinets flash and bleep in the dark, all playing themselves. The Glitch lives in the machines and eats flashlight batteries, the Toon plays rough, and a Partygoer is having the time of its life. Find the prize bell.',
  exitText:'The keypad flashes NEW HIGH SCORE, and the door slides open onto a greenhouse in the rain. Behind you, every cabinet says GAME OVER.',
  flavor:['Every high score on every machine belongs to the same initials: YOU.','A claw machine is full of almond water. The claw is holding one, waiting.','A racing game is playing itself. The car keeps driving into the same wall.','Tokens rain out of a coin slot, then crawl back in.','A cabinet says INSERT COIN, in a voice.']},
 {title:'O Fliperama',exitWhat:'um sino de prêmio tocando no balcão de prêmios',
  intro:'Fileiras de fliperamas piscam e apitam no escuro, todos jogando sozinhos. O Glitch vive nas máquinas e come pilhas de lanterna, o Desenho brinca pesado, e um Festeiro está se divertindo como nunca. Encontre o sino de prêmio.',
  exitText:'O teclado pisca NOVO RECORDE, e a porta desliza para uma estufa na chuva. Atrás de você, todo fliperama diz FIM DE JOGO.',
  flavor:['Todo recorde de toda máquina pertence às mesmas iniciais: VOCÊ.','Uma máquina de garra está cheia de água de amêndoa. A garra segura uma, esperando.','Um jogo de corrida joga sozinho. O carro bate sempre na mesma parede.','Fichas chovem de um caça-níquel, e depois rastejam de volta.','Um fliperama diz INSIRA UMA FICHA, com uma voz.']}),

X(35,{w:12,h:10,loops:0.28,mons:['moths','watcher','lookalike'],dark:0.4,lights:true,hides:3,music:'music35',items:{water:4,fire:2,battery:3,energy:3},
  wall:[120,35,40],floor:[100,30,22],ceil:[180,20,55],amb:'greenhouse',step:'grass',beacon:'birds'},
 {title:'The Greenhouse',exitWhat:'birds singing outside an open window',
  intro:'Glass walls, rain drumming on the roof, and plants that have grown into the shape of hallways. Deathmoths swarm toward any light, so think before you turn your flashlight on. Something stares in through the glass. Listen, and it freezes. Among the watering cans, the Lookalike waits, chiming like something useful. Its chime wavers. Find the birds singing outside an open window.',
  exitText:'You climb out through the window toward the birdsong. Your feet land on concrete. A heavy steel door slams behind you, and a buzzer sounds.',
  flavor:['The plants turn slowly to follow you.','A label on a pot says: do not water after dark.','The rain on the glass sounds like fingers drumming.','A sunflower is taller than you. Its face is not a flower.','Something has been eating the leaves in a perfect, straight line.']},
 {title:'A Estufa',exitWhat:'pássaros cantando do lado de fora de uma janela aberta',
  intro:'Paredes de vidro, chuva batendo no telhado, e plantas que cresceram no formato de corredores. Mariposas da Morte voam em enxame para qualquer luz, então pense antes de ligar a lanterna. Algo encara você através do vidro. Escute, e ele congela. Entre os regadores, o Sósia espera, tilintando como algo útil. O tilintar dele oscila. Encontre os pássaros cantando do lado de fora de uma janela aberta.',
  exitText:'Você sai pela janela na direção do canto. Seus pés pousam no concreto. Uma porta de aço pesada bate atrás de você, e uma campainha toca.',
  flavor:['As plantas viram devagar para seguir você.','Uma etiqueta num vaso diz: não regar depois de escurecer.','A chuva no vidro soa como dedos batucando.','Um girassol é mais alto que você. O rosto dele não é uma flor.','Algo andou comendo as folhas numa linha perfeita e reta.']}),

X(36,{w:12,h:10,loops:0.14,mons:['howler','wretch','wretch'],dark:0.45,lights:true,hides:5,locked:true,music:'music36',items:{water:3,fire:2,battery:3,energy:2,keycard:1},
  wall:[60,5,45],floor:[60,5,30],ceil:[60,5,25],amb:'prison',step:'concrete',beacon:'terminal'},
 {title:'The Prison Block',exitWhat:'the security terminal beeping by the gate',
  intro:'Cell after cell, all of them open, all of them empty. The gate out is locked, and the keycard is somewhere in the block. Listen for its chirp. Two Wretches are loose, and when one sees you, it shrieks and wakes everything. The Howler waits in the dark. There are plenty of hiding spots in the cells. Find the security terminal by the gate.',
  exitText:'You swipe the keycard. The gate grinds open onto a narrow wooden staircase, going up, and up, into a dusty attic where rain drums on the roof.',
  flavor:['A tin cup is rattling against the bars of an empty cell.','Tally marks cover a whole wall. They are still being added.','A loudspeaker announces: lights out. The lights stay on.','Every bunk is made, with perfect corners.','A cell door slams somewhere behind you. Then another. Then another.']},
 {title:'O Bloco Prisional',exitWhat:'o terminal de segurança apitando perto do portão',
  intro:'Cela atrás de cela, todas abertas, todas vazias. O portão para fora está trancado, e o cartão de acesso está em algum lugar do bloco. Escute o bip dele. Dois Miseráveis estão soltos, e quando um vê você, ele grita e acorda tudo. O Uivador espera no escuro. Há muitos esconderijos nas celas. Encontre o terminal de segurança perto do portão.',
  exitText:'Você passa o cartão. O portão se abre rangendo para uma escada estreita de madeira, subindo, e subindo, até um sótão empoeirado onde a chuva bate no telhado.',
  flavor:['Uma caneca de lata bate nas grades de uma cela vazia.','Riscos de contagem cobrem uma parede inteira. Ainda estão sendo feitos.','Um alto-falante anuncia: luzes apagadas. As luzes continuam acesas.','Todo beliche está arrumado, com cantos perfeitos.','Uma porta de cela bate em algum lugar atrás de você. Depois outra. Depois outra.']}),

X(37,{w:11,h:9,loops:0.14,mons:['skin','mimic','wallcrawler'],dark:0.8,lights:false,hides:4,music:'music37',items:{water:3,fire:2,battery:4,energy:2},
  wall:[30,30,30],floor:[28,35,22],ceil:[25,30,15],amb:'attic',step:'wood',beacon:'clock'},
 {title:'The Attic',exitWhat:'an old clock chiming',
  intro:'A dusty attic under a roof that drums with rain, piled with boxes, trunks and covered furniture. The floorboards creak with every step. The Skin-Stealer and the Mimic can sound like people you love, so do not trust a familiar voice up here. The Wall Crawler scratches behind the slanted walls. Keep moving. Find the old clock chiming.',
  exitText:'You open the clock\'s glass door. Behind the pendulum there is water, blue and glowing, and you fall forward into it, slowly, like falling asleep.',
  flavor:['A rocking chair rocks, very slowly, under a sheet.','A box is labelled: things we do not talk about.','The rain on the roof stops. Then you hear footsteps on the roof instead.','An old photo shows your family in front of a house you have never seen.','A doll\'s house sits in the corner. The tiny lights inside are on.']},
 {title:'O Sótão',exitWhat:'um relógio antigo badalando',
  intro:'Um sótão empoeirado debaixo de um telhado onde a chuva bate, cheio de caixas, baús e móveis cobertos. O assoalho range a cada passo. O Ladrão de Pele e o Imitador podem soar como pessoas que você ama, então não confie numa voz conhecida aqui em cima. O Rastejador das Paredes arranha atrás das paredes inclinadas. Continue andando. Encontre o relógio antigo badalando.',
  exitText:'Você abre a portinha de vidro do relógio. Atrás do pêndulo tem água, azul e brilhante, e você cai para a frente dentro dela, devagar, como quem pega no sono.',
  flavor:['Uma cadeira de balanço balança, bem devagar, debaixo de um lençol.','Uma caixa diz: coisas sobre as quais a gente não fala.','A chuva no telhado para. Então você ouve passos no telhado.','Uma foto antiga mostra a sua família na frente de uma casa que você nunca viu.','Uma casinha de bonecas está no canto. As luzinhas dentro estão acesas.']}),

X(38,{w:11,h:8,loops:0.22,mons:['deep','deep','lookalike'],dark:0.35,lights:true,hides:2,water:0.35,memory:true,music:'music26',items:{water:3,fire:2,battery:3,energy:2},
  wall:[195,45,40],floor:[200,35,30],ceil:[205,40,20],amb:'aquarium',step:'tile',beacon:'bubbles'},
 {title:'The Aquarium',exitWhat:'bubbles rising from the drain',
  intro:'Glass tanks taller than houses, glowing blue, with dark shapes drifting inside. Some of the tanks are cracked, and the floor is flooded. Two Things in the Water swim through the flooded halls, so keep to the dry tiles. A Lookalike waits by the gift shop, chiming like a bottle of almond water. Its chime wavers. Find the bubbles rising from the drain.',
  exitText:'The valve turns, and the water drains in a roaring spiral. It pulls you with it, down and around, and spits you out onto wooden boards under a ticking so loud it shakes your bones.',
  flavor:['A fish swims up to the glass and opens its mouth. It has human teeth.','The sign on the biggest tank says: do not tap on the glass. Something inside is tapping.','A shadow the size of a bus passes behind the tanks.','The gift shop sells snow globes of a yellow hallway.','Every tank has the same label: species unknown.']},
 {title:'O Aquário',exitWhat:'bolhas subindo do ralo',
  intro:'Tanques de vidro mais altos que casas, brilhando em azul, com formas escuras flutuando dentro. Alguns tanques estão rachados, e o chão está alagado. Duas Coisas na Água nadam pelos corredores alagados, então fique nos ladrilhos secos. Um Sósia espera perto da loja de lembranças, tilintando como uma garrafa de água de amêndoa. O tilintar dele oscila. Encontre as bolhas subindo do ralo.',
  exitText:'A válvula gira, e a água escoa num redemoinho que ruge. Ela puxa você junto, para baixo e em volta, e cospe você em cima de tábuas de madeira, debaixo de um tique-taque tão alto que treme os ossos.',
  flavor:['Um peixe nada até o vidro e abre a boca. Ele tem dentes humanos.','A placa no maior tanque diz: não bata no vidro. Algo lá dentro está batendo.','Uma sombra do tamanho de um ônibus passa atrás dos tanques.','A loja de lembranças vende globos de neve de um corredor amarelo.','Todo tanque tem a mesma etiqueta: espécie desconhecida.']}),

X(39,{w:11,h:10,loops:0.16,mons:['jester','watcher','wallcrawler'],dark:0.5,lights:true,hides:3,codelock:true,music:'music21',items:{water:3,fire:2,battery:3,energy:2},
  wall:[30,25,35],floor:[25,30,25],ceil:[30,20,20],amb:'last',step:'wood',beacon:'chime'},
 {title:'The Clocktower',exitWhat:'the tower bell chiming the hour',
  intro:'Inside a giant clock. Gears as big as rooms turn slowly overhead, and the ticking never stops. The way out is locked with a keypad, and somebody has scratched its numbers into the walls. The Jester appears out of nowhere, laughing. Something watches through the clock faces. Listen, and it freezes. And the Wall Crawler scratches inside the old wooden walls. Find the tower bell.',
  exitText:'The keypad clicks, and every clock in the tower stops at once. In the silence, the walls turn to glass, and you see a thousand of yourself, all looking back.',
  flavor:['Every clock face shows a different time. None of them are right.','A gear the size of a car turns one tooth, with a sound like a door slamming.','The pendulum swings past, so close you feel the wind.','You count the ticks. Sixty. Sixty-one. Sixty-two.','A cuckoo bursts out of a clock and screams.']},
 {title:'A Torre do Relógio',exitWhat:'o sino da torre batendo a hora',
  intro:'Dentro de um relógio gigante. Engrenagens do tamanho de salas giram devagar lá em cima, e o tique-taque nunca para. A saída está trancada com um teclado, e alguém riscou os números dele nas paredes. O Bobo da Corte aparece do nada, rindo. Algo observa pelos mostradores. Escute, e ele congela. E o Rastejador das Paredes arranha dentro das velhas paredes de madeira. Encontre o sino da torre.',
  exitText:'O teclado estala, e todos os relógios da torre param de uma vez. No silêncio, as paredes viram vidro, e você vê mil de você, todos olhando de volta.',
  flavor:['Cada mostrador marca uma hora diferente. Nenhuma está certa.','Uma engrenagem do tamanho de um carro gira um dente, com um som de porta batendo.','O pêndulo passa tão perto que você sente o vento.','Você conta os tiques. Sessenta. Sessenta e um. Sessenta e dois.','Um cuco sai de um relógio e grita.']}),

X(40,{w:12,h:10,loops:0.3,mons:['skin','skin','mimic','lookalike'],dark:0.45,lights:true,hides:3,music:'music29',items:{water:4,fire:2,battery:3,energy:3},
  wall:[200,10,75],floor:[220,10,35],ceil:[200,10,60],amb:'mirrors',step:'tile',beacon:'piano'},
 {title:'The Hall of Mirrors',exitWhat:'a music box piano playing behind the glass',
  intro:'Mirrors on every wall, reflecting mirrors, reflecting you, forever. Nothing here is what it looks like. Two Skin-Stealers and the Mimic wear familiar faces and voices, and the Lookalike copies the chime of real supplies. Its chime wavers, just slightly. Trust nothing that sounds like a friend. Find the piano playing behind the glass.',
  exitText:'You reach the piano, and your reflection keeps playing after you stop. It smiles, and pushes you through the glass, into a roaring storm drain.',
  flavor:['Your reflection blinks a moment after you do.','In one mirror, the room behind you is empty. In the next, it is not.','Someone has written on a mirror in breath: which one is real?','A reflection waves at you. You did not wave.','You see a door in the mirror. When you turn around, there is no door.']},
 {title:'A Sala dos Espelhos',exitWhat:'um piano de caixinha de música tocando atrás do vidro',
  intro:'Espelhos em todas as paredes, refletindo espelhos, refletindo você, para sempre. Nada aqui é o que parece. Dois Ladrões de Pele e o Imitador usam rostos e vozes conhecidos, e o Sósia copia o tilintar de suprimentos de verdade. O tilintar dele oscila, só um pouquinho. Não confie em nada que soe como um amigo. Encontre o piano tocando atrás do vidro.',
  exitText:'Você chega ao piano, e o seu reflexo continua tocando depois que você para. Ele sorri, e empurra você através do vidro, para dentro de uma galeria pluvial que ruge.',
  flavor:['O seu reflexo pisca um instante depois de você.','Num espelho, a sala atrás de você está vazia. No seguinte, não está.','Alguém escreveu com o bafo num espelho: qual deles é o de verdade?','Um reflexo acena para você. Você não acenou.','Você vê uma porta no espelho. Quando se vira, não tem porta.']}),

X(41,{w:12,h:9,loops:0.2,mons:['deep','hound','static'],dark:0.6,lights:false,hides:2,water:0.35,music:'music34',items:{water:3,fire:3,battery:4,energy:2,radio:1},
  wall:[210,10,30],floor:[210,8,22],ceil:[210,8,15],amb:'storm',step:'concrete',beacon:'wind'},
 {title:'The Storm Drain',exitWhat:'wind howling down a shaft',
  intro:'A huge concrete storm drain, and somewhere above, a storm that never ends. Water pours down the walls and floods the channels. The Thing in the Water hunts in the flooded parts. A Hound howls over the thunder, and the Static drifts through the dark. It hears your walkie-talkie, so keep it quiet. Find the wind howling down a shaft.',
  exitText:'You climb the shaft into the wind. At the top, the storm stops all at once, and the silence is so total you can hear dust settle. Shelves. Thousands of shelves.',
  flavor:['Lightning flashes through a grate above. For a second you see someone standing up there.','A shopping cart is wedged in the drain, full of shoes.','The thunder is so close you feel it in your chest.','The water is rising, a little, every time you look.','A sign says: danger, flash floods. The word flash is underlined in red.']},
 {title:'A Galeria Pluvial',exitWhat:'o vento uivando por um poço',
  intro:'Uma galeria pluvial enorme de concreto, e em algum lugar lá em cima, uma tempestade que nunca acaba. A água escorre pelas paredes e alaga os canais. A Coisa na Água caça nas partes alagadas. Um Cão uiva por cima dos trovões, e a Estática flutua pelo escuro. Ela ouve o seu walkie-talkie, então deixe ele quieto. Encontre o vento uivando por um poço.',
  exitText:'Você sobe o poço contra o vento. Lá em cima, a tempestade para de uma vez, e o silêncio é tão total que dá para ouvir a poeira assentar. Estantes. Milhares de estantes.',
  flavor:['Um relâmpago brilha por uma grade lá em cima. Por um segundo você vê alguém parado lá.','Um carrinho de compras está entalado no bueiro, cheio de sapatos.','O trovão está tão perto que você sente no peito.','A água está subindo, um pouquinho, toda vez que você olha.','Uma placa diz: perigo, enchentes repentinas. A palavra repentinas está sublinhada de vermelho.']}),

X(42,{w:12,h:10,loops:0.18,mons:['librarian','librarian','wallcrawler'],dark:0.55,lights:true,hides:4,puzzle:'lever',music:'music12',items:{water:3,fire:2,battery:3,energy:2},
  wall:[25,45,25],floor:[355,35,20],ceil:[30,30,15],amb:'library',step:'carpet',beacon:'clock'},
 {title:'The Stacks Below',exitWhat:'a grandfather clock ticking in the reading room',
  intro:'Under the Silent Library there is another library, older and darker, where the books are chained to the shelves. Two Librarians patrol it now. When the shushing stops, they are listening, so freeze until it starts again. Never run. And the Wall Crawler scratches behind the shelves, so do not stand still against them for long. Find the grandfather clock ticking in the reading room.',
  exitText:'The secret door swings shut behind you. You are standing in a motel parking lot at night, under a buzzing neon sign. Every room has its light on.',
  flavor:['A book falls off a shelf by itself. It lands open, on a page with your name.','The chains on the books rattle when you walk past.','A card catalog drawer slides open. Every card says: overdue.','Someone has been reading here. The candle is still burning.','The shelves go up so high that the top is lost in the dark.']},
 {title:'As Estantes de Baixo',exitWhat:'um relógio de pêndulo batendo na sala de leitura',
  intro:'Debaixo da Biblioteca Silenciosa existe outra biblioteca, mais antiga e mais escura, onde os livros são acorrentados às estantes. Duas Bibliotecárias patrulham por aqui. Quando o shhh parar, elas estão escutando, então fique parado até ele recomeçar. Nunca corra. E o Rastejador das Paredes arranha atrás das estantes, então não fique encostado nelas por muito tempo. Encontre o relógio de pêndulo batendo na sala de leitura.',
  exitText:'A porta secreta se fecha atrás de você. Você está no estacionamento de um motel à noite, debaixo de um letreiro de néon que zumbe. Todo quarto está com a luz acesa.',
  flavor:['Um livro cai de uma estante sozinho. Ele cai aberto, numa página com o seu nome.','As correntes dos livros tilintam quando você passa.','Uma gaveta do fichário se abre. Toda ficha diz: atrasado.','Alguém estava lendo aqui. A vela ainda está acesa.','As estantes sobem tanto que o topo some no escuro.']}),

X(43,{w:13,h:9,loops:0.2,mons:['bellhop','mimic','janitor'],dark:0.4,lights:true,hides:5,music:'music16',items:{water:3,fire:2,battery:3,energy:2},
  wall:[15,30,40],floor:[20,25,28],ceil:[20,15,30],amb:'motel',step:'carpet',beacon:'buzz'},
 {title:'The Motel',exitWhat:'the neon VACANCY sign buzzing',
  intro:'A roadside motel with a hundred doors, all along one endless walkway. The ice machine rumbles, and a TV laughs behind every wall. The Bellhop knocks politely and offers you a room. Do not take it. The Mimic hums in the voice of someone you miss, and the Janitor\'s cart squeaks along the walkway, cleaning up whatever you leave. Find the buzzing VACANCY sign.',
  exitText:'You reach the sign, and the letters go dark one by one, until only one word is left: NO. The walkway drops away beneath you, and you land on a cold subway platform.',
  flavor:['Every room number is 23.','A DO NOT DISTURB sign swings on a door handle, though there is no wind.','The ice machine drops a single cube. It is red.','A car is parked in front of every room. All of the engines are running.','Through a gap in the curtains, you see someone sitting on a bed, facing the wall.']},
 {title:'O Motel',exitWhat:'o letreiro de néon de VAGAS zumbindo',
  intro:'Um motel de beira de estrada com cem portas, todas ao longo de uma passarela sem fim. A máquina de gelo ronca, e uma TV ri atrás de toda parede. O Mensageiro bate educadamente e oferece um quarto. Não aceite. O Imitador cantarola na voz de alguém de quem você sente falta, e o carrinho do Zelador range pela passarela, limpando tudo o que você deixa. Encontre o letreiro de VAGAS zumbindo.',
  exitText:'Você chega ao letreiro, e as letras se apagam uma por uma, até sobrar uma única palavra: NÃO. A passarela cede sob os seus pés, e você cai numa plataforma de metrô gelada.',
  flavor:['Todo quarto tem o número 23.','Uma placa de NÃO PERTURBE balança na maçaneta, mas não tem vento.','A máquina de gelo solta um único cubo. Ele é vermelho.','Tem um carro estacionado na frente de cada quarto. Todos os motores estão ligados.','Por uma fresta da cortina, você vê alguém sentado numa cama, virado para a parede.']}),

X(44,{w:12,h:9,loops:0.2,mons:['crawler','crawler','static'],dark:0.6,lights:true,hides:4,music:'music22',items:{water:3,fire:2,battery:4,energy:2,radio:1},
  wall:[160,8,30],floor:[0,0,25],ceil:[160,6,18],amb:'metro',step:'concrete',beacon:'train'},
 {title:'The Subway Depths',exitWhat:'a train waiting with its doors open',
  intro:'Below the Last Train there are older tunnels, where the trains still run but nobody rides them. Two Rail Crawlers hunt by sound. When a train roars past, they cannot hear you, so move then. The Static drifts along the tracks. Every time you use your walkie-talkie, it comes for you. Find the train waiting with its doors open.',
  exitText:'You step onto the train, and the doors close. It speeds up and up, until the windows go white, and it stops in a laboratory that smells of bleach and burning wires.',
  flavor:['A subway map on the wall shows only one stop. It is called: here.','Pigeons coo in the dark. There are no pigeons.','The third rail hums, and the hair on your arms stands up.','A conductor\'s cap sits on a bench, still warm.','The tunnel ahead breathes out a long, warm wind.']},
 {title:'As Profundezas do Metrô',exitWhat:'um trem esperando com as portas abertas',
  intro:'Abaixo do Último Trem existem túneis mais antigos, onde os trens ainda passam mas ninguém viaja neles. Dois Rastejadores dos Trilhos caçam pelo som. Quando um trem passa rugindo, eles não conseguem ouvir você, então ande nessa hora. A Estática flutua pelos trilhos. Toda vez que você usa o walkie-talkie, ela vem atrás de você. Encontre o trem esperando com as portas abertas.',
  exitText:'Você entra no trem, e as portas se fecham. Ele acelera e acelera, até as janelas ficarem brancas, e para num laboratório com cheiro de água sanitária e fio queimado.',
  flavor:['Um mapa do metrô na parede mostra uma única estação. Ela se chama: aqui.','Pombos arrulham no escuro. Não tem pombos.','O terceiro trilho zumbe, e os pelos do seu braço arrepiam.','Um quepe de condutor está num banco, ainda quente.','O túnel à frente solta um vento longo e morno.']}),

X(45,{w:12,h:10,loops:0.18,mons:['glitch','clump','lookalike'],dark:0.4,lights:true,hides:4,hazards:0.07,locked:true,music:'music23',items:{water:3,fire:2,battery:4,energy:2,keycard:1},
  wall:[170,15,70],floor:[180,10,55],ceil:[170,10,80],amb:'lab',step:'tile',beacon:'terminal'},
 {title:'The Laboratory',exitWhat:'a containment door terminal beeping',
  intro:'White corridors, broken glass, and humming containment cells, all of them open. Live wires spark across the floor, so listen for the crackle. The containment door is locked, and the keycard is somewhere in the lab. Listen for its chirp. The Glitch eats flashlight batteries, the Clump fills whole corridors, and the Lookalike hides among the supplies. Find the containment door terminal.',
  exitText:'The containment door hisses open. Freezing wind pours in, and you step out onto ice that groans beneath your feet.',
  flavor:['A whiteboard is covered in equations. The last line says: it learned to copy us.','A cage has been bent open from the inside.','A specimen jar is empty. The label says: almond water, sample 1.','The emergency shower is running. Nobody is under it.','A lab coat hangs on a hook, with your name sewn on the pocket.']},
 {title:'O Laboratório',exitWhat:'o terminal de uma porta de contenção apitando',
  intro:'Corredores brancos, vidro quebrado e celas de contenção zumbindo, todas abertas. Fios desencapados soltam faíscas pelo chão, então escute o estalo. A porta de contenção está trancada, e o cartão de acesso está em algum lugar do laboratório. Escute o bip dele. O Glitch come pilhas de lanterna, o Amontoado enche corredores inteiros, e o Sósia se esconde entre os suprimentos. Encontre o terminal da porta de contenção.',
  exitText:'A porta de contenção se abre chiando. Um vento gelado entra, e você sai em cima de um gelo que geme sob os seus pés.',
  flavor:['Um quadro branco está cheio de equações. A última linha diz: ele aprendeu a nos copiar.','Uma jaula foi entortada por dentro.','Um pote de amostra está vazio. A etiqueta diz: água de amêndoa, amostra 1.','O chuveiro de emergência está ligado. Não tem ninguém debaixo dele.','Um jaleco está pendurado num gancho, com o seu nome bordado no bolso.']}),

X(46,{w:12,h:10,loops:0.3,mons:['frost','frost','deep'],dark:0.4,lights:false,hides:2,water:0.25,music:'music17',items:{water:3,fire:3,battery:3,energy:3},
  wall:[205,25,75],floor:[200,20,88],ceil:[215,30,15],amb:'frozen',step:'snow',beacon:'fireplace'},
 {title:'The Frozen Lake',exitWhat:'a fire crackling in an ice fishing hut',
  intro:'A frozen lake under a black sky, with holes cut in the ice. The Frostbitten walk here, slow, and they barely notice you unless you run. Do not run. Under the ice, the Thing in the Water follows your footsteps. Stay away from the open water. Find the fire crackling in an ice fishing hut.',
  exitText:'You warm your hands at the fire inside the hut. When you open the door again, the lake is gone. There is a long pink hallway, and a doll\'s house the size of a real one.',
  flavor:['Under the ice, something pale drifts past, face up.','Your footsteps echo, a moment too late.','A fishing line goes down into a hole in the ice. It is moving.','The snow is falling up.','Somewhere across the lake, someone is skating, in perfect circles.']},
 {title:'O Lago Congelado',exitWhat:'uma fogueira estalando numa cabana de pesca no gelo',
  intro:'Um lago congelado sob um céu preto, com buracos cortados no gelo. Os Congelados andam por aqui, devagar, e quase não percebem você, a não ser que você corra. Não corra. Debaixo do gelo, a Coisa na Água segue os seus passos. Fique longe da água aberta. Encontre a fogueira estalando numa cabana de pesca no gelo.',
  exitText:'Você esquenta as mãos na fogueira dentro da cabana. Quando abre a porta de novo, o lago sumiu. Tem um corredor rosa e comprido, e uma casa de bonecas do tamanho de uma casa de verdade.',
  flavor:['Debaixo do gelo, algo pálido passa flutuando, de barriga para cima.','Seus passos ecoam, um instante atrasados.','Uma linha de pesca desce por um buraco no gelo. Ela está se mexendo.','A neve está caindo para cima.','Do outro lado do lago, alguém está patinando, em círculos perfeitos.']}),

X(47,{w:12,h:10,loops:0.22,mons:['mannequin','mannequin','toon','lookalike'],dark:0.6,lights:false,hides:5,music:'music19',items:{water:3,fire:2,battery:5,energy:2},
  wall:[340,45,75],floor:[30,35,45],ceil:[340,35,85],amb:'home',step:'carpet',beacon:'doorbell'},
 {title:'The Dollhouse',exitWhat:'the dollhouse doorbell ringing',
  intro:'A doll\'s house the size of a real house, with painted wallpaper and furniture that is just a little too small. The dolls here are Mannequins. They cannot move while your light is on them, so keep your flashlight on and bring batteries. The Toon wants to play house, and the Lookalike pretends to be supplies on the tiny kitchen table. Its chime wavers. Find the doorbell ringing.',
  exitText:'You open the front door of the dollhouse. Behind it there is nothing at all. Not dark. Nothing. You step into it, because there is nowhere else to go.',
  flavor:['The dinner table is set for five. There are four dolls.','A painted window shows a painted sky. Something painted is looking in.','The tiny TV is showing a recording of you.','Every family photo on the wall has had one face scratched out.','A doll is sitting on the stairs. You are sure it was not there a moment ago.']},
 {title:'A Casa de Bonecas',exitWhat:'a campainha da casa de bonecas tocando',
  intro:'Uma casa de bonecas do tamanho de uma casa de verdade, com papel de parede pintado e móveis um pouquinho pequenos demais. As bonecas aqui são Manequins. Eles não se mexem enquanto a sua luz está neles, então deixe a lanterna ligada e leve pilhas. O Desenho quer brincar de casinha, e o Sósia finge ser suprimento em cima da mesinha da cozinha. O tilintar dele oscila. Encontre a campainha tocando.',
  exitText:'Você abre a porta da frente da casa de bonecas. Atrás dela não tem nada. Nem escuro. Nada. Você entra, porque não tem para onde ir.',
  flavor:['A mesa do jantar está posta para cinco. Tem quatro bonecas.','Uma janela pintada mostra um céu pintado. Algo pintado está olhando para dentro.','A tevezinha está passando uma gravação de você.','Em toda foto de família na parede, um rosto foi riscado.','Uma boneca está sentada na escada. Você tem certeza de que ela não estava lá agora há pouco.']}),

X(48,{w:12,h:10,loops:0.2,mons:['smiler','smiler','wallcrawler','static'],dark:1,lights:false,hides:3,music:'music36',items:{water:4,fire:3,battery:5,energy:2,radio:1},
  wall:[260,10,12],floor:[260,10,8],ceil:[260,10,5],amb:'void',step:'concrete',beacon:'hum'},
 {title:'The Void Hallway',exitWhat:'a single fluorescent light humming',
  intro:'Total darkness. No walls you can see, no floor you can see, only the sound of your own footsteps. Two Smilers grin in the dark. Your flashlight drives them back, so guard your batteries. The Wall Crawler scratches in walls you cannot see, and the Static drifts toward any radio. Find the one fluorescent light, humming somewhere in the black.',
  exitText:'You reach the light. Under it is a yellow carpet, wet and stained, and wallpaper you know. The Lobby. But it is rotten now, and something is breathing in the walls.',
  flavor:['You hold your hand in front of your face. You cannot see it.','Your footsteps stop echoing. Then they start again, from behind you.','A voice whispers your name, very close, and very calm.','The darkness has a smell: old paper, and almond water.','Something brushes past your arm. It was soft, and it was warm.']},
 {title:'O Corredor do Vazio',exitWhat:'uma única lâmpada fluorescente zumbindo',
  intro:'Escuridão total. Nenhuma parede que dê para ver, nenhum chão que dê para ver, só o som dos seus passos. Dois Sorridentes sorriem no escuro. A lanterna afasta eles, então guarde as pilhas. O Rastejador das Paredes arranha em paredes que você não vê, e a Estática flutua até qualquer rádio. Encontre a única lâmpada fluorescente, zumbindo em algum lugar no preto.',
  exitText:'Você chega à luz. Debaixo dela tem um carpete amarelo, molhado e manchado, e um papel de parede que você conhece. O Saguão. Mas agora ele está podre, e algo respira dentro das paredes.',
  flavor:['Você põe a mão na frente do rosto. Não consegue ver.','Seus passos param de ecoar. Depois recomeçam, atrás de você.','Uma voz sussurra o seu nome, bem perto, e bem calma.','A escuridão tem cheiro: papel velho, e água de amêndoa.','Algo roça no seu braço. Era macio, e era quente.']}),

X(49,{w:13,h:10,loops:0.2,mons:['host','wretch','janitor','lookalike'],dark:0.6,lights:true,hides:4,music:'music30',items:{water:4,fire:3,battery:4,energy:3},
  wall:[55,40,35],floor:[40,35,22],ceil:[55,20,45],amb:'rot',step:'carpet',beacon:'buzz'},
 {title:'The Rotting Lobby',exitWhat:'the old exit sign, buzzing',
  intro:'The Lobby, where it all started. But it has been rotting for years. The wallpaper peels, the carpet squelches, and the lights flicker brown. The Host walks here, speaking in voices you love. Flares drive it back. A Wretch shrieks, the Janitor mops the rot around in circles, and the Lookalike pretends to be the supplies you need so badly. Find the old exit sign.',
  exitText:'The exit sign flickers, and spells a new word: FIFTY. The door behind it opens onto a long, quiet hallway, and every sound you have heard in the Backrooms is waiting there.',
  flavor:['A mushroom grows out of the wallpaper in the shape of a hand.','The carpet is so wet that every step makes a sound like a kiss.','The tape player you started with is lying on the floor, still running.','Someone has written on the wall in mold: you came back.','The hum of the lights is lower now, like a voice gone hoarse.']},
 {title:'O Saguão Apodrecido',exitWhat:'a velha placa de saída, zumbindo',
  intro:'O Saguão, onde tudo começou. Mas ele está apodrecendo há anos. O papel de parede descasca, o carpete faz barulho de molhado, e as luzes piscam marrons. O Anfitrião anda por aqui, falando com vozes que você ama. Sinalizadores afastam ele. Um Miserável grita, o Zelador espalha a podridão em círculos com o esfregão, e o Sósia finge ser os suprimentos de que você tanto precisa. Encontre a velha placa de saída.',
  exitText:'A placa de saída pisca, e soletra uma palavra nova: CINQUENTA. A porta atrás dela se abre para um corredor comprido e silencioso, e todo som que você ouviu nos Backrooms está esperando lá.',
  flavor:['Um cogumelo cresce do papel de parede no formato de uma mão.','O carpete está tão molhado que cada passo faz um barulho de beijo.','O gravador com que você começou está no chão, ainda rodando.','Alguém escreveu na parede com mofo: você voltou.','O zumbido das luzes está mais grave agora, como uma voz rouca.']}),

X(50,{w:14,h:11,loops:0.2,mons:['wallcrawler','lookalike','static','janitor','hound'],dark:0.5,lights:true,hides:4,locked:true,music:'music31',items:{water:5,fire:3,battery:5,energy:3,radio:1,keycard:1},
  wall:[48,40,58],floor:[30,25,38],ceil:[50,15,80],amb:'fifty',step:'carpet',beacon:'radio'},
 {title:'The Fiftieth Door',exitWhat:'a radio playing a song you remember',
  intro:'A long, quiet hallway where every sound of the Backrooms echoes at once: a phone, a train, a music box, rain. Everything you survived is here. The Wall Crawler scratches in the walls, so keep moving. The Lookalike hides among the supplies, chiming. Listen for the waver. The Static hunts your radio, the Janitor cleans up behind you, and a Hound is on your trail. The last door is locked. Find the keycard, then the radio playing a song you remember.',
  exitText:'You swipe the keycard, and the fiftieth door opens. Daylight, for a moment. Then the light flickers, and hums, and turns yellow. Level fifty-one. The Backrooms keep going, and so do you.',
  flavor:['A door in the wall has the number 50 on it, painted over 49, painted over 48.','You hear the Lobby\'s hum, the Hospital\'s monitor, and the Hotel\'s chime, all at once.','A wall is covered in names. Near the bottom, written in your handwriting, is yours.','Somewhere, a tape player clicks on. A tired voice says: you made it further than I did.','The air smells like rain, and outside, and home.']},
 {title:'A Quinquagésima Porta',exitWhat:'um rádio tocando uma música de que você se lembra',
  intro:'Um corredor comprido e silencioso onde todos os sons dos Backrooms ecoam de uma vez: um telefone, um trem, uma caixinha de música, chuva. Tudo o que você sobreviveu está aqui. O Rastejador das Paredes arranha nas paredes, então continue andando. O Sósia se esconde entre os suprimentos, tilintando. Escute a oscilação. A Estática caça o seu rádio, o Zelador limpa atrás de você, e um Cão está no seu rastro. A última porta está trancada. Encontre o cartão de acesso, e depois o rádio tocando uma música de que você se lembra.',
  exitText:'Você passa o cartão, e a quinquagésima porta se abre. Luz do dia, por um momento. Depois a luz pisca, e zumbe, e fica amarela. Nível cinquenta e um. Os Backrooms continuam, e você também.',
  flavor:['Uma porta na parede tem o número 50, pintado por cima do 49, pintado por cima do 48.','Você ouve o zumbido do Saguão, o monitor do Hospital e o sino do Hotel, tudo ao mesmo tempo.','Uma parede está coberta de nomes. Perto do chão, com a sua letra, está o seu.','Em algum lugar, um gravador liga. Uma voz cansada diz: você foi mais longe do que eu.','O ar tem cheiro de chuva, e de lá fora, e de casa.']})
);
})();
